<script setup lang="ts">import {Head,Link,useForm} from '@inertiajs/vue3';const props=defineProps<{submission:any;statuses:string[]}>();const statusForm=useForm({status:'',reason:''});const revisionForm=useForm({fields:[] as string[],message:'',deadline_at:''});</script>
<template><Head :title="submission.registration_number"/><div class="min-h-screen bg-neutral-100 p-6"><main class="mx-auto max-w-6xl"><Link href="/admin/submissions" class="text-sm">← Semua submission</Link><div class="mt-5 flex justify-between"><div><h1 class="text-4xl font-bold">{{submission.song.title}}</h1><p class="font-mono text-orange-700">{{submission.registration_number}}</p></div><b>{{submission.status}}</b></div><div class="mt-8 grid gap-6 lg:grid-cols-[1fr_.7fr]"><section class="space-y-6"><article class="card"><h2>Pendaftar</h2><dl><div><dt>Nama</dt><dd>{{submission.applicant.full_name}}</dd></div><div><dt>Email</dt><dd>{{submission.applicant.email}}</dd></div><div><dt>WhatsApp</dt><dd>{{submission.applicant.whatsapp}}</dd></div><div><dt>Domisili</dt><dd>{{submission.applicant.city}}, {{submission.applicant.province}}</dd></div></dl><a v-for="file in submission.files" :key="file.id" :href="`/admin/files/${file.id}`" class="mt-4 inline-block text-orange-700">Unduh {{file.type.toUpperCase()}}</a></article><article class="card"><h2>Lagu</h2><p class="mt-4 whitespace-pre-line text-neutral-700">{{submission.song.story}}</p></article></section><aside class="space-y-6"><form class="card" @submit.prevent="statusForm.patch(`/admin/submissions/${submission.id}/status`)"><h2>Ubah status</h2><select v-model="statusForm.status" required><option value="">Pilih status</option><option v-for="s in statuses" :key="s">{{s}}</option></select><textarea v-model="statusForm.reason" placeholder="Alasan wajib" required></textarea><button>Simpan status</button><p v-for="e in statusForm.errors" :key="e" class="error">{{e}}</p></form><form class="card" @submit.prevent="revisionForm.post(`/admin/submissions/${submission.id}/revision-requests`)"><h2>Minta revisi</h2><label v-for="f in ['data_diri','lagu','demo','video','dokumen']" :key="f" class="check"><input v-model="revisionForm.fields" type="checkbox" :value="f"> {{f}}</label><textarea v-model="revisionForm.message" placeholder="Catatan revisi" required></textarea><input v-model="revisionForm.deadline_at" type="datetime-local" required><button>Kirim permintaan</button></form></aside></div></main></div></template>
<style scoped>.card{border-radius:1rem;background:white;padding:1.5rem;box-shadow:0 1px 3px #0001}.card h2{font-size:1.25rem;font-weight:700}.card dl{display:grid;gap:1rem;margin-top:1.25rem}.card dt{font-size:.75rem;text-transform:uppercase;color:#737373}.card dd{font-weight:600}.card form{display:grid}select,textarea,input{width:100%;margin-top:1rem;border:1px solid #d4d4d4;border-radius:.75rem;padding:.75rem}.card button{margin-top:1rem;border-radius:.75rem;background:#171717;color:white;padding:.75rem}.check{display:flex;gap:.5rem;margin-top:.75rem}.check input{width:auto;margin:0}.error{font-size:.75rem;color:#dc2626}</style>
